      );
      if (this.session.sheet() === sheet) this.crews.update((list) => [...list, saved]);
      this.name.set('');
      this.lead.set('');
    } catch {
      this.error.set(`The crew could not be added: ${name} may already be one.`);
    } finally {
      this.adding = false;
    }
  }

